// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.executionimport com.roshan.persona.cognitive.model.CognitiveConfigimport com.roshan.persona.cognitive.model.ReasoningTraceimport com.roshan.persona.cognitive.model.StoredReasoningTraceimport com.roshan.persona.cognitive.model.UserFeedbackimport java.util.concurrent.ConcurrentHashMapimport java.util.concurrent.atomic.AtomicLong/** * NOUS — Reasoning Trace Store (Module 7 v2 — Step 7.7, P2). * * Persistent storage of reasoning traces so the user can revisit why NOUS * recommended X — even months later. * * ## Features (per strategy v2 §"ReasoningTraceStore" + Q7) * *  - **30-day TTL** — traces older than 30 days are auto-deleted. *  - **User-deletable** — "forget why you recommended X" deletes the trace. *  - **Queryable** — "show me why you recommended the train" finds matching traces. *  - **User feedback** — tracks ACCEPTED / REJECTED / CORRECTED per trace *    (for PreferenceLearner in v3). * * ## v1 storage * * In-memory (ConcurrentHashMap). Resets on app restart. v3+ will use Room * for persistence (same pattern as Module 10's PersistentUndoStack + * Module 3's Memory). * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§ReasoningTraceStore</a> */class ReasoningTraceStore(    private val config: CognitiveConfig = CognitiveConfig(),) {    private val traces = ConcurrentHashMap<String, StoredReasoningTrace>()    private val nextId = AtomicLong(1)    /**     * Store a reasoning trace.     *     * @param userQuery the original user query.     * @param trace the reasoning trace.     * @param nowMs current epoch time (injectable for testing).     * @return the stored trace ID.     */    fun store(        userQuery: String,        trace: ReasoningTrace,        nowMs: Long = System.currentTimeMillis(),    ): String {        val traceId = "trace_${nextId.getAndIncrement()}"        val stored = StoredReasoningTrace(            traceId = traceId,            timestamp = nowMs,            userQuery = userQuery,            trace = trace,        )        traces[traceId] = stored        // Enforce max stored traces (LRU eviction).        if (traces.size > config.maxStoredTraces) {            evictOldest()        }        // Cleanup expired.        cleanup(nowMs)        return traceId    }    /**     * Get a stored trace by ID.     *     * @return the stored trace, or null if not found or expired.     */    fun get(traceId: String, nowMs: Long = System.currentTimeMillis()): StoredReasoningTrace? {        val stored = traces[traceId] ?: return null        if (isExpired(stored, nowMs)) {            traces.remove(traceId)            return null        }        return stored    }    /**     * Find stored traces matching [query] (case-insensitive substring match).     *     * @param query the search query ("why did you recommend the train").     * @param limit max results (default 10).     * @return matching traces, most-recent-first.     */    fun search(query: String, limit: Int = 10, nowMs: Long = System.currentTimeMillis()): List<StoredReasoningTrace> {        val lower = query.lowercase().trim()        return traces.values            .filter { !isExpired(it, nowMs) }            .filter { it.userQuery.lowercase().contains(lower) || it.trace.finalAnswer.lowercase().contains(lower) }            .sortedByDescending { it.timestamp }            .take(limit)    }    /**     * Get recent traces (for UI history list).     *     * @param limit max results (default 20).     * @return most-recent traces.     */    fun getRecent(limit: Int = 20, nowMs: Long = System.currentTimeMillis()): List<StoredReasoningTrace> {        return traces.values            .filter { !isExpired(it, nowMs) }            .sortedByDescending { it.timestamp }            .take(limit)    }    /**     * Record user feedback on a trace.     *     * @param traceId the trace ID.     * @param feedback the user's feedback.     * @param correctionNote optional correction note (if CORRECTED).     */    fun recordFeedback(        traceId: String,        feedback: UserFeedback,        correctionNote: String? = null,    ) {        val stored = traces[traceId] ?: return        traces[traceId] = stored.copy(            userFeedback = feedback,            correctionNote = correctionNote,        )    }    /**     * Delete a specific trace (user: "forget why you recommended X").     *     * @return true if a trace was deleted.     */    fun delete(traceId: String): Boolean {        return traces.remove(traceId) != null    }    /** Clear all stored traces. */    fun clear() {        traces.clear()    }    /** Number of stored traces (including expired — call [cleanup] first for accurate count). */    fun count(): Int = traces.size    /** Remove expired traces (older than [CognitiveConfig.traceStorageTtlDays]). */    fun cleanup(nowMs: Long = System.currentTimeMillis()) {        val iterator = traces.entries.iterator()        while (iterator.hasNext()) {            if (isExpired(iterator.next().value, nowMs)) {                iterator.remove()            }        }    }    /** Check if a trace is expired. */    private fun isExpired(stored: StoredReasoningTrace, nowMs: Long): Boolean {        val ttlMs = config.traceStorageTtlDays * 24L * 60 * 60 * 1000        return nowMs - stored.timestamp > ttlMs    }    /** Evict the oldest trace (by timestamp). */    private fun evictOldest() {        val oldest = traces.minByOrNull { it.value.timestamp }        if (oldest != null) {            traces.remove(oldest.key)        }    }}